USE Restaurant_Management_System;

-- Q1. Top 10 Selling Menu Items
select menu.ItemName, count(orders.MenuID) as TimesOrderred 
from Menu
Inner Join orders
on menu.MenuID = orders.MenuID
group by menu.ItemName
order by TimesOrderred desc
limit 10;
/* BUSINESS INSIGHTS :- To Decides which Food item has best sales.
To Increase their stock*/


-- Q2. Highest Revenue Generated by Employees
select employees.EmployeeName, sum(orders.TotalAmount) as Generated_Revenue from employees
Inner Join orders
on employees.EmployeeID = orders.EmployeeID
group by employees.EmployeeName
order by Generated_Revenue desc;
/* BUSINESS INSIGHTS :- To decides which employee gain maximum sales.
To give him incentive or Bonus.*/


-- Q3. Monthly Restaurant Revenue
select monthname(PaymentDate) as Months , sum(Amount) as Total_Revenue from payments
group by Months
order by Total_Revenue desc;
/* BUSINESS INSIGHTS :- This shows which months generate the highest and lowest sales.
To Plan accordingly in the Festival seasons.*/


-- Q4. Payment Method Analysis
select PaymentMethod, count(PaymentID) as Total_Transactions, sum(Amount) as Total_Collection
from payments
group by PaymentMethod;
/* BUSINESS INSIGHTS :- To Know customer used which payment method most (UPI,CASH,CARD,Net Banking).
So Restaurant can improve their Payment Facilities.*/

-- Q5. To Check the status of orders.
select Status , count(orderID) as Total_Orders from orders
group by Status;
/* BUSINESS INSIGHTS :- To Understand the (Completed, Pending, Cancelled) counts.
If Cancelled orders is high then Restaurant Needs to improve their services.*/

-- Q6. Top Selling Items with High , medieum ,Low Category
Select MenuID, TotalAmount , 
case
When TotalAmount > 1000 Then "HIGH SALE"
When TotalAmount > 500 Then "MEDIUM SALE"
Else "LOW SALE"
End As Selling_Category
from orders;
/* BUSINESS INSIGHTS :- To Understand which dish is most popular or best selling dish to 
increase their inventary and stocks */


-- Q7. Who are the Top 5 Highest Spending Customers?
 SELECT customers.CustomerID, customers.CustomerName,
    SUM(orders.TotalAmount) AS Total_Spent,
    RANK() OVER(ORDER BY SUM(orders.TotalAmount) DESC) AS CustomerRank
FROM Customers 
LEFT JOIN Orders 
ON customers.CustomerID = orders.CustomerID
GROUP BY customers.CustomerID, customers.CustomerName
LIMIT 5;
/* BUSINESS INSIGHTS :- This identifies the top spending customers. 
The restaurant can offer personalized discounts to these valuable customers. */

 
 -- Waq to find products that are either electronics or having price > 1 lakh and find top 3 products
 Select products , Category ,Price from Table_Namee
 where Category = "Electronics" or Price > 100000
 group by Category
 order by Price Desc 
 limit 3 ;
 
 -- Find departments that currently had no employyes
 Select Departments , Employees from Table_Namee
 where department is null;
 
 
 